BEGIN;
CREATE TABLE IF NOT EXISTS customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_id uuid NOT NULL REFERENCES entities(id),customer_code varchar(50) NOT NULL,name varchar(255) NOT NULL,email varchar(320),phone varchar(50),credit_limit numeric(20,2),payment_terms_days integer NOT NULL DEFAULT 30 CHECK(payment_terms_days>=0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(entity_id,customer_code));
CREATE TABLE IF NOT EXISTS invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_id uuid NOT NULL REFERENCES entities(id),customer_id uuid NOT NULL REFERENCES customers(id),invoice_number varchar(60) NOT NULL,invoice_date date NOT NULL,due_date date NOT NULL,currency char(3) NOT NULL,subtotal numeric(20,2) NOT NULL CHECK(subtotal>=0),tax_amount numeric(20,2) NOT NULL DEFAULT 0 CHECK(tax_amount>=0),total_amount numeric(20,2) NOT NULL CHECK(total_amount>=0),status varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','SENT','PARTIALLY_PAID','PAID','OVERDUE','WRITTEN_OFF','VOID')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(entity_id,invoice_number),CHECK(due_date>=invoice_date));
CREATE TABLE IF NOT EXISTS customer_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_id uuid NOT NULL REFERENCES invoices(id),payment_date date NOT NULL,amount numeric(20,2) NOT NULL CHECK(amount>0),reference varchar(100),created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_invoice_customer_due ON invoices(customer_id,due_date);
COMMIT;
